import sys
import io
from rich.console import Console
from rich.file_proxy import FileProxy

class MockFile(io.TextIOBase):
    def write(self, s):
        pass
    def flush(self):
        pass

def test_file_proxy_isatty_missing():
    console = Console(file=sys.stdout)
    mock_file = MockFile()
    proxy = FileProxy(console, mock_file)

    print("Testing proxy.isatty() when underlying file has no isatty()")
    try:
        print(f"proxy.isatty(): {proxy.isatty()}")
    except AttributeError as e:
        print(f"Caught expected AttributeError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_file_proxy_isatty_missing()

import sys
import io
from rich.console import Console
from rich.file_proxy import FileProxy

class MockFile(io.TextIOBase):
    def write(self, s):
        pass
    def flush(self):
        pass
    def isatty(self):
        return True

def test_file_proxy_isatty_true():
    console = Console(file=sys.stdout)
    mock_file = MockFile()
    proxy = FileProxy(console, mock_file)

    print(f"mock_file.isatty(): {mock_file.isatty()}")
    print(f"proxy.isatty(): {proxy.isatty()}")

    assert proxy.isatty() == mock_file.isatty()

if __name__ == "__main__":
    test_file_proxy_isatty_true()

